examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var accuracy: Int?
@State private var tone: Int?
@State private var notes = ""
@State private var verdict: String?

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    Text("Score \((accuracy ?? 0) + (tone ?? 0)) / 8").monarchTextStyle(.bodyStrong)
    Text("Facts match the source or reference.")
        .monarchTextStyle(.caption)
        .foregroundStyle(theme.colors.textMuted)
    MonarchRatingPicker("Accuracy", value: $accuracy, isClearable: true)
    MonarchRatingPicker("Tone", value: $tone, in: 1...3, isClearable: true)
    MonarchFormField("Notes") {
        TextField("Notes", text: $notes, axis: .vertical)
            .lineLimit(3...8)
    }
    Picker("Verdict", selection: $verdict) {
        Text("Pass").tag("pass" as String?)
        Text("Fail").tag("fail" as String?)
    }
    .pickerStyle(.segmented)
}
